def calculate_ratio(x, y, z):
    P = (2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1)
    Q = x*y + y*z + z*x
    if Q == 0:
        return None # Should not happen for positive x, y, z
    return P / Q

sets = [
    (1, 2, 3),
    (0.5, 1, 2),
    (1, 1.5, 2),
    (0.1, 2, 3),
    (0.2, 1.5, 2.5)
]

results = {}
for i, (x, y, z) in enumerate(sets):
    ratio = calculate_ratio(x, y, z)
    results[f"Set {i+1} ({x}, {y}, {z})"] = ratio

for key, value in results.items():
    print(f"{key}: {value}")

